import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  sin,
  dot,
  fract,
  positionLocal,
  normalWorld,
  normalize as tslNormalize,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    CylinderGeometry,
    TorusKnotGeometry,
    TorusGeometry,
    PlaneGeometry,
    CircleGeometry,
    Color,
    DirectionalLight,
    HemisphereLight,
    DoubleSide,
  } = ctx.THREE;

  const root = new Group();
  root.name = 'pedestal-material-study';

  const colors =
    config.colors ??
    config.intent?.visualSpec?.colors ?? {
      background: '#0b0b10',
      surface: '#14141a',
      ink: '#16161d',
      paper: '#e8ecf2',
      accent: '#ff2a38',
      gradientStops: [
        { at: 0, hex: '#0b0b10' },
        { at: 0.7, hex: '#101017' },
        { at: 1, hex: '#16161d' },
      ],
    };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Material study 03', role: 'headline', typography: { fontSize: 68 } },
      { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption', typography: { fontSize: 18 } },
    ];

  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  // ---------------------------------------------------------------
  // BACKDROP — 7x6 plane at z=-3 carrying the vertical gradient
  // ---------------------------------------------------------------
  const stops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 0.7, hex: colors.surface ?? '#101017' },
    { at: 1, hex: colors.ink },
  ];
  const toVec3 = (hex) => {
    const c = new Color(hex);
    return vec3(c.r, c.g, c.b);
  };
  const c0 = toVec3(stops[0].hex);
  const c1 = toVec3(stops[1] ? stops[1].hex : stops[0].hex);
  const c2 = toVec3(stops[stops.length - 1].hex);

  const t = uv().y;
  const stageColor = mix(mix(c0, c1, smoothstep(float(0.0), float(stops[1] ? stops[1].at : 0.7), t)), c2, smoothstep(float(stops[1] ? stops[1].at : 0.7), float(1.0), t));

  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = stageColor;
  backdropMat.side = DoubleSide;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  root.add(backdrop);
  disposables.push(() => backdropGeo.dispose(), () => backdropMat.dispose());

  // ---------------------------------------------------------------
  // PEDESTAL — cylinder radius 1.1, height 0.5, top face at y=-0.35
  // ---------------------------------------------------------------
  const pedestalGeo = new CylinderGeometry(1.1, 1.1, 0.5, 64);
  const pedestalMat = new MeshPhysicalNodeMaterial();
  pedestalMat.color = new Color(colors.surface ?? '#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.6, 0);
  root.add(pedestal);
  disposables.push(() => pedestalGeo.dispose(), () => pedestalMat.dispose());

  // chamfered top edge — thin ring catching key light
  const chamferGeo = new TorusGeometry(1.09, 0.03, 12, 64);
  const chamferMat = new MeshPhysicalNodeMaterial();
  chamferMat.color = new Color(colors.surface ?? '#14141a');
  chamferMat.roughness = 0.4;
  chamferMat.metalness = 0.5;
  chamferMat.clearcoat = 0.15;
  const chamfer = new Mesh(chamferGeo, chamferMat);
  chamfer.rotation.x = Math.PI / 2;
  chamfer.position.set(0, -0.35, 0);
  root.add(chamfer);
  disposables.push(() => chamferGeo.dispose(), () => chamferMat.dispose());

  // ---------------------------------------------------------------
  // CONTACT SHADOW — radial gradient plane at y=-0.36
  // ---------------------------------------------------------------
  const shadowGeo = new CircleGeometry(1.5, 64);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const localXZ = positionLocal;
  const dist = localXZ.x.mul(localXZ.x).add(localXZ.y.mul(localXZ.y)).sqrt();
  const shadowOpacity = float(0.6).mul(float(1.0).sub(smoothstep(float(1.1), float(1.5), dist)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = shadowOpacity;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  root.add(shadow);
  disposables.push(() => shadowGeo.dispose(), () => shadowMat.dispose());

  // ---------------------------------------------------------------
  // TORUS KNOT — brushed metal PBR hero subject
  // ---------------------------------------------------------------
  const hash = (uvNode) => fract(sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453));

  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial();
  knotMat.color = new Color(0xb8b8bd);
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  // procedural imperfection pass: fine value jitter (2%) via hash noise
  const jitterUv = uv().mul(50.0);
  const jitter = hash(jitterUv).sub(0.5).mul(0.02);
  knotMat.roughnessNode = float(0.55).add(jitter);

  // scratch-noise normal perturbation, strength 0.15
  const scratchUv = uv().mul(300.0);
  const scratch = hash(scratchUv);
  const scratchB = hash(scratchUv.add(vec2(13.7, 91.3)));
  const perturb = vec3(scratch.sub(0.5), scratchB.sub(0.5), 0.0).mul(0.15);
  knotMat.normalNode = tslNormalize(normalWorld.add(perturb));

  const knot = new Mesh(knotGeo, knotMat);
  knot.position.set(0, 0.4, 0);
  root.add(knot);
  disposables.push(() => knotGeo.dispose(), () => knotMat.dispose());

  // roughness map (brushed-metal texture) — multiplies, centered ~0.9
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = 1000; // RepeatWrapping numeric fallback-safe
      const mapSample = texture(tex).r;
      const centered = mapSample.mul(0.2).add(0.9);
      knotMat.roughnessNode = float(0.55).mul(centered).add(jitter);
      knotMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------------------------------------------------------------
  // LIGHTS — node-local rim/accent + environment approximation
  // ---------------------------------------------------------------
  const rim = new DirectionalLight(new Color(colors.accent ?? '#ff2a38'), 0.75);
  rim.position.set(-2.5, 1.5, -2.0);
  root.add(rim);

  const envFill = new HemisphereLight(new Color(0xf2f2f5), new Color(0x0b0b10), 0.7);
  root.add(envFill);

  disposables.push(() => rim.dispose && rim.dispose(), () => envFill.dispose && envFill.dispose());

  // ---------------------------------------------------------------
  // TEXT
  // ---------------------------------------------------------------
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const captionItem = items.find((i) => i.role === 'caption') ?? items[1];

  let headline = null;
  let caption = null;

  if (headlineItem) {
    headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
    });
    headline.position.set(0, -1.2, 0.01);
    root.add(headline);
  }

  if (captionItem) {
    caption = ctx.fontAtlas.createText(captionItem.text, {
      fontSize: captionItem.typography?.fontSize ?? 18,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
      letterSpacingPx: 1.4,
    });
    caption.position.set(0, -1.6, 0.01);
    root.add(caption);
  }

  // ---------------------------------------------------------------
  // ENTRANCE MOTION — weighted-settle
  // ---------------------------------------------------------------
  knot.scale.setScalar(0.001);
  root.position.y = -0.3;
  const settleTl = gsap.timeline();
  settleTl.to(root.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  settleTl.to(
    knot.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.5,
      ease: 'power2.out',
      onComplete: () => {
        gsap.to(knot.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
      },
    },
    0.05
  );
  timelines.push(settleTl);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const applyFn = ctx.primitives[primitive.name];
    if (typeof applyFn === 'function') {
      const target = knot;
      const handle = applyFn(target, primitive.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle.timeline?.kill?.();
      handle.cleanup?.();
    }
    for (const dispose of disposables) {
      try {
        dispose();
      } catch (e) {
        /* noop */
      }
    }
    headline?.userData?.dispose?.();
    caption?.userData?.dispose?.();
    root.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose?.();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose?.());
        } else {
          child.material?.dispose?.();
        }
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
